-- 20260925162000_documental_fiscal_contract_release_v3
alter table public.facturas add column if not exists contrato_id uuid references public.contratos(id) on delete restrict,add column if not exists empresa_receptor_id uuid references public.empresas(id) on delete restrict,add column if not exists producto_id integer references public.productos(id) on delete restrict,add column if not exists cantidad_tn numeric,add column if not exists tipo_comprobante_codigo integer,add column if not exists punto_venta integer,add column if not exists numero_comprobante bigint,add column if not exists cuit_emisor text,add column if not exists cuit_receptor text,add column if not exists razon_social_emisor text,add column if not exists razon_social_receptor text,add column if not exists condicion_iva_receptor integer,add column if not exists importe_neto numeric,add column if not exists importe_iva numeric,add column if not exists importe_total numeric,add column if not exists cae text,add column if not exists caea text,add column if not exists cae_vencimiento date,add column if not exists arca_environment text,add column if not exists arca_service text,add column if not exists arca_resultado text,add column if not exists arca_codigo text,add column if not exists arca_mensaje text,add column if not exists arca_request_id text,add column if not exists arca_request_xml text,add column if not exists arca_response_xml text,add column if not exists arca_autorizado_at timestamptz,add column if not exists usuario_responsable uuid references auth.users(id),add column if not exists creada_en timestamptz default now(),add column if not exists actualizada_en timestamptz default now();
create table if not exists public.factura_eventos(id uuid primary key default gen_random_uuid(),factura_id uuid not null references public.facturas(id) on delete restrict,evento text not null,actor_profile_id uuid references auth.users(id),metadata jsonb not null default '{}'::jsonb,creado_en timestamptz not null default now());
create table if not exists public.contrato_versiones(id uuid primary key default gen_random_uuid(),contrato_id uuid not null references public.contratos(id) on delete restrict,version integer not null,estado text not null default 'BORRADOR',motivo text,contenido text not null,archivo_docx text,archivo_pdf text,documento_hash text,creado_por uuid not null references auth.users(id),creado_en timestamptz not null default now(),unique(contrato_id,version));
create table if not exists public.plantillas_contrato(id uuid primary key default gen_random_uuid(),codigo text unique not null,nombre text not null,tipo_contrato text not null,version integer not null default 1,activa boolean not null default true,clausulas jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.factura_eventos enable row level security;alter table public.contrato_versiones enable row level security;alter table public.plantillas_contrato enable row level security;
revoke insert,update,delete on public.facturas,public.factura_eventos,public.contrato_versiones,public.plantillas_contrato from anon,authenticated;
drop policy if exists facturas_select_participante on public.facturas;create policy facturas_select_participante on public.facturas for select to authenticated using(public.usuario_participa_operacion(operacion_id));
drop policy if exists facturas_deny_insert on public.facturas;create policy facturas_deny_insert on public.facturas for insert to authenticated with check(false);
drop policy if exists facturas_deny_update on public.facturas;create policy facturas_deny_update on public.facturas for update to authenticated using(false) with check(false);
drop policy if exists facturas_deny_delete on public.facturas;create policy facturas_deny_delete on public.facturas for delete to authenticated using(false);
drop policy if exists factura_eventos_select_participante on public.factura_eventos;create policy factura_eventos_select_participante on public.factura_eventos for select to authenticated using(exists(select 1 from public.facturas f where f.id=factura_id and public.usuario_participa_operacion(f.operacion_id)));
drop policy if exists contrato_versiones_select_participante on public.contrato_versiones;create policy contrato_versiones_select_participante on public.contrato_versiones for select to authenticated using(exists(select 1 from public.contratos c where c.id=contrato_id and public.usuario_participa_operacion(c.operacion_id)));
drop policy if exists plantillas_contrato_select_auth on public.plantillas_contrato;create policy plantillas_contrato_select_auth on public.plantillas_contrato for select to authenticated using(activa);
create unique index if not exists ux_facturas_fiscal_number on public.facturas(empresa_id,punto_venta,tipo_comprobante_codigo,numero_comprobante) where punto_venta is not null and tipo_comprobante_codigo is not null and numero_comprobante is not null;
create or replace function public.crear_solicitud_factura(p_operacion_id uuid,p_empresa_receptor_id uuid,p_tipo_comprobante_codigo integer,p_punto_venta integer,p_importe_neto numeric,p_importe_iva numeric,p_fecha_emision date default current_date,p_fecha_vencimiento date default null,p_condicion_iva_receptor integer default null) returns uuid language plpgsql security definer set search_path=public as $$declare v_uid uuid:=auth.uid();v_empresa uuid;v_contrato uuid;v_producto integer;v_cantidad numeric;v_moneda integer;v_total numeric;v_id uuid;v_issuer public.empresas%rowtype;v_receiver public.empresas%rowtype;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select active_company_id into v_empresa from public.profiles where id=v_uid;if v_empresa is null or not public.usuario_es_miembro_empresa(v_empresa) then raise exception 'ACTIVE_COMPANY_REQUIRED';end if;if not public.usuario_participa_operacion(p_operacion_id) then raise exception 'FORBIDDEN';end if;select id into v_contrato from public.contratos where operacion_id=p_operacion_id and estado='CONFIRMADO' limit 1;if v_contrato is null then raise exception 'CONFIRMED_CONTRACT_REQUIRED';end if;if not exists(select 1 from public.operacion_participantes where operacion_id=p_operacion_id and empresa_id=v_empresa) then raise exception 'ISSUER_NOT_PARTICIPANT';end if;if not exists(select 1 from public.operacion_participantes where operacion_id=p_operacion_id and empresa_id=p_empresa_receptor_id) then raise exception 'RECEIVER_NOT_PARTICIPANT';end if;if p_importe_neto<=0 or coalesce(p_importe_iva,0)<0 then raise exception 'INVALID_AMOUNTS';end if;v_total:=round(p_importe_neto+coalesce(p_importe_iva,0),2);select cantidad_tn,moneda_id into v_cantidad,v_moneda from public.operaciones where id=p_operacion_id;select * into v_issuer from public.empresas where id=v_empresa;select * into v_receiver from public.empresas where id=p_empresa_receptor_id;select producto_id into v_producto from public.publicaciones where id in((select publicacion_venta_id from public.operaciones where id=p_operacion_id) union all(select publicacion_compra_id from public.operaciones where id=p_operacion_id)) and producto_id is not null limit 1;insert into public.facturas(operacion_id,empresa_id,contrato_id,empresa_receptor_id,producto_id,cantidad_tn,tipo_factura,tipo_comprobante_codigo,punto_venta,importe,importe_neto,importe_iva,importe_total,moneda_id,fecha_emision,fecha_vencimiento,estado,cuit_emisor,cuit_receptor,razon_social_emisor,razon_social_receptor,condicion_iva_receptor,usuario_responsable,creada_en,actualizada_en)values(p_operacion_id,v_empresa,v_contrato,p_empresa_receptor_id,v_producto,v_cantidad,case p_tipo_comprobante_codigo when 1 then 'A' when 6 then 'B' when 11 then 'C' when 51 then 'M' else 'OTRO' end,p_tipo_comprobante_codigo,p_punto_venta,p_importe_neto,p_importe_neto,p_importe_iva,v_total,v_moneda,p_fecha_emision,p_fecha_vencimiento,'PENDIENTE_ARCA',v_issuer.cuit,v_receiver.cuit,v_issuer.razon_social,v_receiver.razon_social,p_condicion_iva_receptor,v_uid,now(),now())returning id into v_id;insert into public.factura_eventos(factura_id,actor_profile_id,evento,metadata)values(v_id,v_uid,'SOLICITADA_ARCA',jsonb_build_object('tipo_comprobante',p_tipo_comprobante_codigo));return v_id;end;$$;
revoke all on function public.crear_solicitud_factura(uuid,uuid,integer,integer,numeric,numeric,date,date,integer) from public,anon;grant execute on function public.crear_solicitud_factura(uuid,uuid,integer,integer,numeric,numeric,date,date,integer) to authenticated;
create or replace function public.crear_version_contrato(p_contrato_id uuid,p_motivo text,p_contenido text,p_estado text default 'BORRADOR') returns uuid language plpgsql security definer set search_path=public as $$declare v_uid uuid:=auth.uid();v_op uuid;v_next integer;v_id uuid;v_hash text;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select operacion_id into v_op from public.contratos where id=p_contrato_id;if v_op is null or not public.usuario_participa_operacion(v_op) then raise exception 'FORBIDDEN';end if;if exists(select 1 from public.contratos where id=p_contrato_id and estado='CONFIRMADO') then raise exception 'CONFIRMED_CONTRACT_IMMUTABLE';end if;if nullif(trim(p_contenido),'') is null then raise exception 'CONTENT_REQUIRED';end if;select coalesce(max(version),0)+1 into v_next from public.contrato_versiones where contrato_id=p_contrato_id;v_hash:=encode(digest(convert_to(p_contenido,'utf8'),'sha256'),'hex');insert into public.contrato_versiones(contrato_id,version,estado,motivo,contenido,documento_hash,creado_por)values(p_contrato_id,v_next,p_estado,trim(p_motivo),p_contenido,v_hash,v_uid)returning id into v_id;return v_id;end;$$;
revoke all on function public.crear_version_contrato(uuid,text,text,text) from public,anon;grant execute on function public.crear_version_contrato(uuid,text,text,text) to authenticated;